CREATE OR REPLACE FUNCTION minicore.fn_update_account_balance()
RETURNS TRIGGER AS $$
DECLARE
    v_amount    NUMERIC(18,2);
    v_available NUMERIC(18,2);
    v_collected NUMERIC(18,2);
BEGIN
    -- Determine signed amount based on direction
    IF NEW.direction = 'CREDIT' THEN
        v_amount := NEW.amount;
    ELSE
        v_amount := -NEW.amount;
    END IF;

    -- REVERSED flips the sign
    IF NEW.status = 'REVERSED' THEN
        v_amount := -v_amount;
    END IF;

    -- Apply to balances based on status and capture resulting balances
    IF NEW.status = 'PENDING' THEN
        UPDATE minicore.accounts
        SET collected_balance = collected_balance + v_amount,
            updated_at = NOW()
        WHERE account_id = NEW.account_id
        RETURNING available_balance, collected_balance
        INTO v_available, v_collected;
    ELSE
        UPDATE minicore.accounts
        SET available_balance = available_balance + v_amount,
            collected_balance = collected_balance + v_amount,
            updated_at = NOW()
        WHERE account_id = NEW.account_id
        RETURNING available_balance, collected_balance
        INTO v_available, v_collected;
    END IF;

    -- Record the post-transaction balance snapshot
    INSERT INTO minicore.transaction_balances (transaction_id, account_id, available_balance, collected_balance)
    VALUES (NEW.transaction_id, NEW.account_id, v_available, v_collected);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_outbox_transactions()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO minicore.outbox_transactions
        (operation_type, transaction_id, account_id, transaction_code, amount, direction, status, json_payload, effective_date, transaction_created_at)
    VALUES
        ('INSERT', NEW.transaction_id, NEW.account_id, NEW.transaction_code, NEW.amount, NEW.direction, NEW.status, NEW.json_payload, NEW.effective_date, NEW.created_at);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_populate_accounts_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO minicore.outbox_accounts_sync_wait_confirmation (event_id, bulk_id)
    SELECT event_id, NEW.bulk_id
    FROM minicore.outbox_accounts
    WHERE event_id BETWEEN NEW.first_event_id AND NEW.last_event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_populate_transactions_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO minicore.outbox_transactions_sync_wait_confirmation (event_id, bulk_id)
    SELECT event_id, NEW.bulk_id
    FROM minicore.outbox_transactions
    WHERE event_id BETWEEN NEW.first_event_id AND NEW.last_event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_cleanup_accounts_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    DELETE FROM minicore.outbox_accounts_sync_wait_confirmation
    WHERE event_id = NEW.event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_cleanup_transactions_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    DELETE FROM minicore.outbox_transactions_sync_wait_confirmation
    WHERE event_id = NEW.event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_check_effect_consistency()
RETURNS TRIGGER AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM minicore.transaction_code_balance_effects
        WHERE transaction_code = NEW.transaction_code
          AND effect != NEW.effect
    ) THEN
        RAISE EXCEPTION 'Transaction code % cannot have opposite signs for different balances', NEW.transaction_code;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql
